package com.rumitx.app.repeaters;
import android.content.*;import android.database.*;import android.database.sqlite.*;import java.io.*;import java.util.*;
public final class RepeaterDatabase extends SQLiteOpenHelper {
 public RepeaterDatabase(Context c){super(c,"repeaters.db",null,1);}
 public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE repeaters (id INTEGER PRIMARY KEY,callsign TEXT,name TEXT,freq_out REAL,freq_in REAL,offset_mhz REAL,tone_in TEXT,tone_out TEXT,dcs_in TEXT,dcs_out TEXT,mode TEXT,dmr_cc INTEGER,dmr_ts INTEGER,dmr_tg TEXT,dmr_id TEXT,lat REAL,lon REAL,city TEXT,county TEXT,state TEXT,status TEXT,use_restriction TEXT,source TEXT,updated INTEGER)");d.execSQL("CREATE INDEX repeaters_location ON repeaters(lat,lon)");d.execSQL("CREATE INDEX repeaters_state ON repeaters(state)");d.execSQL("CREATE UNIQUE INDEX repeaters_identity ON repeaters(callsign,name,freq_out,mode,state,source)");d.execSQL("CREATE TABLE channel_links(channel_id INTEGER PRIMARY KEY,repeater_id INTEGER,block_reason TEXT)");}
 public void onUpgrade(SQLiteDatabase d,int oldV,int newV){}
 public long save(Repeater r){ContentValues v=new ContentValues();v.put("callsign",r.callsign);v.put("name",r.name);v.put("freq_out",r.output);if(r.input!=null){v.put("freq_in",r.input);v.put("offset_mhz",r.offset());}else{v.putNull("freq_in");v.putNull("offset_mhz");}v.put("tone_in",r.toneIn);v.put("tone_out",r.toneOut);v.put("dcs_in",r.dcsIn);v.put("dcs_out",r.dcsOut);v.put("mode",r.mode);if(r.cc!=null)v.put("dmr_cc",r.cc);else v.putNull("dmr_cc");if(r.ts!=null)v.put("dmr_ts",r.ts);else v.putNull("dmr_ts");v.put("dmr_tg",r.tg);v.put("dmr_id",r.dmrId);if(r.located()){v.put("lat",r.latitude);v.put("lon",r.longitude);}else{v.putNull("lat");v.putNull("lon");}v.put("city",r.city);v.put("county",r.county);v.put("state",r.state);v.put("status",r.status);v.put("use_restriction",r.restriction);v.put("source",r.source);v.put("updated",r.updated);
  String where="callsign=? AND name=? AND freq_out=? AND mode=? AND state=? AND source=?";String[] args={r.callsign,r.name,String.valueOf(r.output),r.mode,r.state,r.source};SQLiteDatabase d=getWritableDatabase();if(r.id>0){d.update("repeaters",v,"id=?",new String[]{""+r.id});com.rumitx.app.tak.TakService.repeatersChanged();return r.id;}try(Cursor c=d.query("repeaters",new String[]{"id"},where,args,null,null,null)){if(c.moveToFirst()){r.id=c.getLong(0);d.update("repeaters",v,"id=?",new String[]{""+r.id});com.rumitx.app.tak.TakService.repeatersChanged();return r.id;}}r.id=d.insertOrThrow("repeaters",null,v);com.rumitx.app.tak.TakService.repeatersChanged();return r.id;
 }
 public static class ImportResult {public int imported,skipped,withoutLocation;public String toString(){return imported+" repeaters imported, "+skipped+" rows skipped; "+withoutLocation+" without location.";}}
 public ImportResult importCsv(Reader reader)throws IOException {ImportResult result=new ImportResult();SQLiteDatabase d=getWritableDatabase();d.beginTransaction();try(CsvReader csv=new CsvReader(reader)){List<String> header=csv.next();if(header==null)throw new IOException("CSV is empty");boolean hasFrequency=false;for(String h:header)if(Arrays.asList("frequency","freqout","outputfrequency","output","outputfreq").contains(RepeaterParser.norm(h)))hasFrequency=true;if(!hasFrequency)throw new IOException("No output-frequency column. Use RepeaterBook or CHIRP CSV.");List<String> cells;int lines=0;while((cells=csv.next())!=null){if(++lines>100000)throw new IOException("CSV exceeds 100,000 rows");if(cells.size()==1&&cells.get(0).trim().isEmpty())continue;try{if(cells.size()!=header.size())throw new IllegalArgumentException();Map<String,String> row=new HashMap<>();for(int i=0;i<header.size();i++)row.put(header.get(i),cells.get(i));Repeater r=RepeaterParser.parse(row);save(r);result.imported++;if(!r.located())result.withoutLocation++;}catch(IllegalArgumentException e){result.skipped++;}}d.setTransactionSuccessful();return result;}finally{d.endTransaction();}}
 private Repeater read(Cursor c){Repeater r=new Repeater();r.id=c.getLong(c.getColumnIndexOrThrow("id"));r.callsign=text(c,"callsign");r.name=text(c,"name");r.output=c.getDouble(c.getColumnIndexOrThrow("freq_out"));r.input=decimal(c,"freq_in");r.latitude=decimal(c,"lat");r.longitude=decimal(c,"lon");r.toneIn=text(c,"tone_in");r.toneOut=text(c,"tone_out");r.dcsIn=text(c,"dcs_in");r.dcsOut=text(c,"dcs_out");r.mode=text(c,"mode");r.cc=integer(c,"dmr_cc");r.ts=integer(c,"dmr_ts");r.tg=text(c,"dmr_tg");r.dmrId=text(c,"dmr_id");r.city=text(c,"city");r.county=text(c,"county");r.state=text(c,"state");r.status=text(c,"status");r.restriction=text(c,"use_restriction");r.source=text(c,"source");r.updated=c.getLong(c.getColumnIndexOrThrow("updated"));return r;}
 private String text(Cursor c,String k){String s=c.getString(c.getColumnIndexOrThrow(k));return s==null?"":s;}private Double decimal(Cursor c,String k){int i=c.getColumnIndexOrThrow(k);return c.isNull(i)?null:c.getDouble(i);}private Integer integer(Cursor c,String k){int i=c.getColumnIndexOrThrow(k);return c.isNull(i)?null:c.getInt(i);}
 public List<Repeater> list(String where,String[] args,String order,int limit){List<Repeater> rows=new ArrayList<>();try(Cursor c=getReadableDatabase().query("repeaters",null,where,args,null,null,order,String.valueOf(limit))){while(c.moveToNext())rows.add(read(c));}return rows;}
 public List<Repeater> all(){return list(null,null,"callsign,name",2000);}
 public List<Repeater> box(double south,double west,double north,double east,int limit){String lon=west<=east?"lon BETWEEN ? AND ?":"(lon>=? OR lon<=?)";return list("lat BETWEEN ? AND ? AND "+lon,new String[]{""+south,""+north,""+west,""+east},"callsign",limit);}
 public List<Repeater> nearest(double lat,double lon,double radius){double dy=radius/110.574,dx=Math.min(180,radius/(111.32*Math.max(.0001,Math.cos(Math.toRadians(lat)))));List<Repeater> rows=dx>=180?list("lat BETWEEN ? AND ? AND lon IS NOT NULL",new String[]{""+Math.max(-90,lat-dy),""+Math.min(90,lat+dy)},null,100000):box(Math.max(-90,lat-dy),Geo.wrap(lon-dx),Math.min(90,lat+dy),Geo.wrap(lon+dx),100000);Collections.sort(rows,(a,b)->Double.compare(Geo.distanceKm(lat,lon,a.latitude,a.longitude),Geo.distanceKm(lat,lon,b.latitude,b.longitude)));List<Repeater> out=new ArrayList<>();for(Repeater r:rows)if(Geo.distanceKm(lat,lon,r.latitude,r.longitude)<=radius&&out.size()<200)out.add(r);return out;}
 public void updateProfile(long id,Repeater r){r.id=id;save(r);}
 public long linkedChannel(long repeater){try(Cursor c=getReadableDatabase().query("channel_links",new String[]{"channel_id"},"repeater_id=?",new String[]{""+repeater},null,null,null)){return c.moveToFirst()?c.getLong(0):0;}}
 public long count(){try(Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM repeaters",null)){c.moveToFirst();return c.getLong(0);}}
 public void link(long channel,long repeater,String reason){ContentValues v=new ContentValues();v.put("channel_id",channel);v.put("repeater_id",repeater);v.put("block_reason",reason);getWritableDatabase().insertWithOnConflict("channel_links",null,v,SQLiteDatabase.CONFLICT_REPLACE);}
 public String block(long channel){try(Cursor c=getReadableDatabase().query("channel_links",new String[]{"block_reason"},"channel_id=?",new String[]{""+channel},null,null,null)){return c.moveToFirst()?c.getString(0):null;}}
}
